pragma solidity ^0.8.24;

import {Initializable} from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

interface IKotaAccessSBTReceiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data)
        external returns (bytes4);
}

interface IKotaTenantRegistryFactory {
    function adminRegistry() external view returns (address);
    function deployTenantRegistryOnApproval(
        string calldata tenantId,
        address tenantOperator,
        string[] calldata initialOrigins
    ) external returns (address registry);
}

/// @title KotaAccessSBT — soulbound access credential for the Kota Router
/// @notice Non-transferable (ERC-5192 locked) ERC-721 used as on-chain proof of
///         access. The router verifies `balanceOf(wallet) >= 1` via eth_call
///         after the wallet proves control with a personal_sign signature.
///
///         Deployment model:
///           * The PLATFORM deploys one instance for tenant credentials and one
///             for admin credentials (or one instance using roles).
///           * Each TENANT may deploy their own instance (or reuse any ERC-721/
///             ERC-1155 they already operate) as the user registry for their
///             tenant public-key route.
///
///         Tokens cannot be transferred or approved — only minted by the issuer
///         and burned by the issuer (revocation) or the holder (renounce).
contract KotaAccessSBT is Initializable {
    // ---------------------------------------------------------------- events
    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    /// @dev ERC-5192: locked at mint; temporarily unlocked only by issuer approval.
    event Locked(uint256 tokenId);
    event Unlocked(uint256 tokenId);
    event TransferApproved(uint256 indexed tokenId, address indexed to);
    event TransferApprovalCancelled(uint256 indexed tokenId);
    event IssuerChanged(address indexed previousIssuer, address indexed newIssuer);
    event AccessGranted(address indexed holder, uint256 indexed tokenId, uint8 role);
    event AccessRevoked(address indexed holder, uint256 indexed tokenId, uint8 role);
    event TierCreated(uint32 indexed tierId, string label);
    event TierMetadataUpdated(uint32 indexed tierId);
    event TierAssigned(address indexed holder, uint32 indexed tierId);
    event TierFeaturesUpdated(uint32 indexed tierId, uint256 features);
    event TierActiveChanged(uint32 indexed tierId, bool active);
    event TenantApproved(
        address indexed tenantOperator,
        uint32 indexed tierId,
        string tenantId,
        address indexed registry
    );

    error UnknownTier();
    error NotHolder();

    // ---------------------------------------------------------------- errors
    error NotIssuer();
    error Soulbound();
    error AlreadyHolder();
    error UnknownToken();
    error ZeroAddress();
    error NotAuthorizedToBurn();
    error UnsafeRecipient();
    error AlreadyInitialized();
    error InvalidRole();
    error TierInactive();
    error InvalidTierFeatures();
    error InvalidFactory();
    error ExistingCredentialRoleMismatch();
    error BatchLengthMismatch();
    error BatchTooLarge();
    error DuplicateTenantOperator();
    error DuplicateTenantId();
    error InvalidTenantId();

    // ---------------------------------------------------------------- roles
    /// Hierarchical credential roles. Numeric role 0 remains valid for legacy
    /// non-privileged credentials, but is intentionally not exposed as a new UI
    /// integration surface. Tenant end users belong in tenant registries.
    uint8 public constant ROLE_TENANT = 1;
    uint8 public constant ROLE_ADMIN = 2;
    uint8 public constant ROLE_SYSTEM = 3;
    uint256 public constant FEATURE_COLLECTION_METADATA = 1 << 0;
    uint256 public constant FEATURE_PER_TOKEN_METADATA = 1 << 1;
    uint256 public constant SUPPORTED_TIER_FEATURES =
        FEATURE_COLLECTION_METADATA | FEATURE_PER_TOKEN_METADATA;
    uint256 public constant MAX_TENANT_APPROVAL_BATCH = 10;
    uint256 public constant MAX_ACCESS_GRANT_BATCH = 100;

    // ---------------------------------------------------------------- state
    string public name;
    string public symbol;
    /// @notice The credential issuer (platform or tenant operator wallet).
    address public issuer;
    uint256 public totalMinted;

    mapping(uint256 tokenId => address holder) private _ownerOf;
    mapping(address holder => uint256 count) private _balanceOf;
    mapping(uint256 tokenId => uint8 role) public roleOf;
    /// @notice One credential per wallet keeps registry semantics unambiguous.
    mapping(address holder => uint256 tokenId) public tokenOf;
    /// @notice Issuer-approved one-time transfer destination per token.
    mapping(uint256 tokenId => address to) private _approvedTransferTo;

    // ---- appendable admin-defined tenant tiers (optional; 0 = default) ----
    // The issuer appends plan tiers post-deploy (e.g. starter/pro/enterprise)
    // and assigns them to tenant credentials; unassigned holders are tier 0.
    uint32 public tierCount; // ids 1..tierCount; 0 is the implicit default
    mapping(uint32 => string) public tierLabel;
    mapping(uint32 => string) public tierMetadata; // plan rules blob/URI
    mapping(address => uint32) public tierOf;      // holder -> tier (0 default)

    /// Structured, machine-readable plan limits enforced ON-CHAIN by the
    /// factory (not just off-chain metadata). Registering a tier validates
    /// minimum requirements so a malformed tier can never brick deployments.
    struct TierLimits {
        uint256 maxRegistries;          // user registries deployable (>= 1 required)
        uint256 maxHoldersPerRegistry;  // per-registry user cap (0 = unlimited)
    }
    mapping(uint32 => TierLimits) public tierLimits;
    /// Optional capabilities granted by each platform tier. Appended after the
    /// deployed layout; zero is the safe default for pre-existing tiers.
    mapping(uint32 => uint256) public tierFeatures;
    /// Negative storage preserves upgrade semantics: every tier that existed
    /// before this field was added remains active because its value is false.
    mapping(uint32 => bool) private _tierDisabled;
    // Append-only recovery epochs. Epoch zero preserves pre-upgrade approvals.
    uint256 public authorityEpoch;
    mapping(uint256 => uint256) private _transferApprovalEpoch;
    event AuthorityPermissionsInvalidated(uint256 epoch);
    event TierLimitsUpdated(uint32 indexed tierId, uint256 maxRegistries, uint256 maxHoldersPerRegistry);
    error TierMinimumRequirements();

    modifier onlyIssuer() {
        if (msg.sender != issuer) revert NotIssuer();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // ---- proxy initializer (OpenZeppelin TransparentUpgradeableProxy) ----
    /// @notice Runs once behind the proxy (storage starts zeroed, so
    ///         issuer == 0). Sets the initial admin as issuer and MINTS the
    ///         admin credential (ROLE_ADMIN) to that address immediately.
    ///         Upgrades are governed by the external ProxyAdmin, not here.
    function initialize(string calldata name_, string calldata symbol_, address initialAdmin)
        external initializer
    {
        // Retain the state sentinel for proxies initialized by the pre-v1.0.2
        // implementation, whose Initializable version slot was not yet set.
        if (issuer != address(0)) revert AlreadyInitialized();
        if (initialAdmin == address(0)) revert ZeroAddress();
        name = name_;
        symbol = symbol_;
        issuer = initialAdmin;
        emit IssuerChanged(address(0), initialAdmin);
        uint256 tokenId = ++totalMinted;
        _ownerOf[tokenId] = initialAdmin;
        _balanceOf[initialAdmin] = 1;
        roleOf[tokenId] = ROLE_ADMIN;
        tokenOf[initialAdmin] = tokenId;
        emit Transfer(address(0), initialAdmin, tokenId);
        emit Locked(tokenId);
        emit AccessGranted(initialAdmin, tokenId, ROLE_ADMIN);
    }

    // ------------------------------------------------------------ erc-165
    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return
            interfaceId == 0x01ffc9a7 || // ERC-165
            interfaceId == 0x80ac58cd || // ERC-721
            interfaceId == 0x5b5e139f || // ERC-721 Metadata
            interfaceId == 0xb45a3c0e;   // ERC-5192 Minimal Soulbound
    }

    // ------------------------------------------------------------ erc-5192
    /// @notice Locked unless the issuer has approved a pending transfer.
    /// @notice Effective approval; changing authority invalidates all older approvals.
    function approvedTransferTo(uint256 tokenId) public view returns (address) {
        return _transferApprovalEpoch[tokenId] == authorityEpoch
            ? _approvedTransferTo[tokenId] : address(0);
    }

    function locked(uint256 tokenId) external view returns (bool) {
        if (_ownerOf[tokenId] == address(0)) revert UnknownToken();
        return approvedTransferTo(tokenId) == address(0);
    }

    // ------------------------------------------------------------- erc-721
    function balanceOf(address holder) external view returns (uint256) {
        if (holder == address(0)) revert ZeroAddress();
        return _balanceOf[holder];
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        address holder = _ownerOf[tokenId];
        if (holder == address(0)) revert UnknownToken();
        return holder;
    }

    function tokenURI(uint256 tokenId) external view returns (string memory) {
        if (_ownerOf[tokenId] == address(0)) revert UnknownToken();
        return "";
    }

    // Transfers execute ONLY along an issuer-approved escrow path.
    /// @notice Issuer pre-approves a one-time transfer of a credential.
    function approveTransfer(uint256 tokenId, address to) external onlyIssuer {
        if (_ownerOf[tokenId] == address(0)) revert UnknownToken();
        if (to == address(0)) revert ZeroAddress();
        if (_balanceOf[to] != 0) revert AlreadyHolder();
        _approvedTransferTo[tokenId] = to;
        _transferApprovalEpoch[tokenId] = authorityEpoch;
        emit TransferApproved(tokenId, to);
        emit Unlocked(tokenId);
    }

    function cancelTransferApproval(uint256 tokenId) external onlyIssuer {
        if (_ownerOf[tokenId] == address(0)) revert UnknownToken();
        delete _approvedTransferTo[tokenId];
        emit TransferApprovalCancelled(tokenId);
        emit Locked(tokenId);
    }

    // ---- tier management (issuer plane) ----
    /// @notice Registering a tier requires minimum viable limits up front:
    ///         at least one deployable user registry.
    function createTier(
        string calldata label,
        string calldata metadata,
        uint256 maxRegistries_,
        uint256 maxHoldersPerRegistry_
    ) external onlyIssuer returns (uint32 tierId) {
        if (maxRegistries_ == 0) revert TierMinimumRequirements();
        tierId = ++tierCount;
        tierLabel[tierId] = label;
        tierMetadata[tierId] = metadata;
        tierLimits[tierId] = TierLimits(maxRegistries_, maxHoldersPerRegistry_);
        emit TierCreated(tierId, label);
        emit TierLimitsUpdated(tierId, maxRegistries_, maxHoldersPerRegistry_);
    }

    function setTierLimits(uint32 tierId, uint256 maxRegistries_, uint256 maxHoldersPerRegistry_)
        external onlyIssuer
    {
        if (tierId == 0 || tierId > tierCount) revert UnknownTier();
        if (maxRegistries_ == 0) revert TierMinimumRequirements();
        tierLimits[tierId] = TierLimits(maxRegistries_, maxHoldersPerRegistry_);
        emit TierLimitsUpdated(tierId, maxRegistries_, maxHoldersPerRegistry_);
    }

    function setTierMetadata(uint32 tierId, string calldata metadata) external onlyIssuer {
        if (tierId == 0 || tierId > tierCount) revert UnknownTier();
        tierMetadata[tierId] = metadata;
        emit TierMetadataUpdated(tierId);
    }

    function setTierFeatures(uint32 tierId, uint256 features) external onlyIssuer {
        if (tierId == 0 || tierId > tierCount) revert UnknownTier();
        if (features & ~SUPPORTED_TIER_FEATURES != 0) revert InvalidTierFeatures();
        tierFeatures[tierId] = features;
        emit TierFeaturesUpdated(tierId, features);
    }

    function tierActive(uint32 tierId) public view returns (bool) {
        return tierId != 0 && tierId <= tierCount && !_tierDisabled[tierId];
    }

    function setTierActive(uint32 tierId, bool active) external onlyIssuer {
        if (tierId == 0 || tierId > tierCount) revert UnknownTier();
        _tierDisabled[tierId] = !active;
        emit TierActiveChanged(tierId, active);
    }

    function assignTier(address holder, uint32 tierId) public onlyIssuer {
        if (tierId > tierCount) revert UnknownTier(); // 0 resets to default
        if (tierId != 0 && !tierActive(tierId)) revert TierInactive();
        if (_balanceOf[holder] == 0) revert NotHolder();
        tierOf[holder] = tierId;
        emit TierAssigned(holder, tierId);
    }

    function assignTierBatch(address[] calldata holders, uint32 tierId) external onlyIssuer {
        if (holders.length == 0 || holders.length > MAX_ACCESS_GRANT_BATCH) revert BatchTooLarge();
        if (tierId > tierCount) revert UnknownTier();
        if (tierId != 0 && !tierActive(tierId)) revert TierInactive();
        for (uint256 i = 0; i < holders.length; i++) {
            if (holders[i] == address(0)) revert ZeroAddress();
        }
        for (uint256 i = 0; i < holders.length; i++) {
            if (_balanceOf[holders[i]] != 0) {
                tierOf[holders[i]] = tierId;
                emit TierAssigned(holders[i], tierId);
            }
        }
    }

    /// @notice Executes only when it matches the issuer's approval exactly;
    ///         callable by the holder or the issuer. Re-locks after transfer.
    function transferFrom(address from, address to, uint256 tokenId) public {
        address holder = _ownerOf[tokenId];
        if (holder == address(0)) revert UnknownToken();
        if (holder != from || msg.sender != holder && msg.sender != issuer) revert Soulbound();
        if (to == address(0)) revert ZeroAddress();
        if (approvedTransferTo(tokenId) != to) revert Soulbound();
        if (_balanceOf[to] != 0) revert AlreadyHolder();
        delete _approvedTransferTo[tokenId];
        delete tokenOf[from];
        _balanceOf[from] = 0;
        _ownerOf[tokenId] = to;
        _balanceOf[to] = 1;
        tokenOf[to] = tokenId;
        // Tier assignment follows the credential to the new wallet.
        tierOf[to] = tierOf[from];
        delete tierOf[from];
        emit Transfer(from, to, tokenId);
        emit Locked(tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        transferFrom(from, to, tokenId);
        _checkOnERC721Received(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes calldata data) external {
        transferFrom(from, to, tokenId);
        _checkOnERC721Received(from, to, tokenId, data);
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data)
        private
    {
        if (to.code.length == 0) return;
        try IKotaAccessSBTReceiver(to).onERC721Received(msg.sender, from, tokenId, data)
            returns (bytes4 response)
        {
            if (response != IKotaAccessSBTReceiver.onERC721Received.selector) {
                revert UnsafeRecipient();
            }
        } catch {
            revert UnsafeRecipient();
        }
    }

    function approve(address, uint256) external pure {
        revert Soulbound();
    }

    function setApprovalForAll(address, bool) external pure {
        revert Soulbound();
    }

    function getApproved(uint256) external pure returns (address) {
        return address(0);
    }

    function isApprovedForAll(address, address) external pure returns (bool) {
        return false;
    }

    // ---------------------------------------------------------- credential ops
    function _mintCredential(address holder, uint8 role) private returns (uint256 tokenId) {
        tokenId = ++totalMinted;
        _ownerOf[tokenId] = holder;
        _balanceOf[holder] = 1;
        roleOf[tokenId] = role;
        tokenOf[holder] = tokenId;
        emit Transfer(address(0), holder, tokenId);
        emit Locked(tokenId);
        emit AccessGranted(holder, tokenId, role);
    }

    /// @notice Issue an access credential to a wallet. One per wallet.
    function grantAccess(address holder, uint8 role) external onlyIssuer returns (uint256 tokenId) {
        if (holder == address(0)) revert ZeroAddress();
        if (role > ROLE_SYSTEM) revert InvalidRole();
        if (_balanceOf[holder] != 0) revert AlreadyHolder();
        tokenId = _mintCredential(holder, role);
    }

    /// @notice Batch issuance for onboarding existing registries.
    function grantAccessBatch(address[] calldata holders, uint8 role) external onlyIssuer {
        if (role > ROLE_SYSTEM) revert InvalidRole();
        if (holders.length == 0 || holders.length > MAX_ACCESS_GRANT_BATCH) revert BatchTooLarge();
        for (uint256 i = 0; i < holders.length; i++) {
            if (holders[i] == address(0)) revert ZeroAddress();
        }
        for (uint256 i = 0; i < holders.length; i++) {
            address holder = holders[i];
            if (_balanceOf[holder] != 0) continue; // idempotent onboarding
            _mintCredential(holder, role);
        }
    }

    function _validateTenantFactory(address factory) private view {
        if (factory == address(0) || factory.code.length == 0) revert InvalidFactory();
        if (IKotaTenantRegistryFactory(factory).adminRegistry() != address(this)) {
            revert InvalidFactory();
        }
    }

    function _approveTenantAndDeploy(
        address factory,
        address tenantOperator,
        uint32 tierId,
        string calldata tenantId,
        string[] calldata initialOrigins
    ) private returns (address registry) {
        _validateTenantApproval(tenantOperator, tierId, tenantId);
        uint256 tokenId = tokenOf[tenantOperator];
        if (tokenId == 0) {
            _mintCredential(tenantOperator, ROLE_TENANT);
        } else if (roleOf[tokenId] != ROLE_TENANT) {
            revert ExistingCredentialRoleMismatch();
        }
        tierOf[tenantOperator] = tierId;
        emit TierAssigned(tenantOperator, tierId);
        registry = IKotaTenantRegistryFactory(factory).deployTenantRegistryOnApproval(
            tenantId,
            tenantOperator,
            initialOrigins
        );
        emit TenantApproved(tenantOperator, tierId, tenantId, registry);
    }

    function _validateTenantApproval(
        address tenantOperator,
        uint32 tierId,
        string calldata tenantId
    ) private view {
        if (tenantOperator == address(0)) revert ZeroAddress();
        if (bytes(tenantId).length == 0) revert InvalidTenantId();
        if (!tierActive(tierId)) revert TierInactive();
        uint256 tokenId = tokenOf[tenantOperator];
        if (tokenId != 0 && roleOf[tokenId] != ROLE_TENANT) {
            revert ExistingCredentialRoleMismatch();
        }
    }

    /// @notice Atomically grant a tenant credential, assign its active plan,
    ///         and deploy the first tenant user registry with baseline branding.
    function approveTenantAndDeploy(
        address factory,
        address tenantOperator,
        uint32 tierId,
        string calldata tenantId,
        string[] calldata initialOrigins
    ) external onlyIssuer returns (address registry) {
        _validateTenantFactory(factory);
        registry = _approveTenantAndDeploy(
            factory, tenantOperator, tierId, tenantId, initialOrigins
        );
    }

    /// @notice Bounded atomic batch form. Any invalid approval or failed
    ///         registry deployment reverts every credential and registry write.
    function approveTenantsAndDeploy(
        address factory,
        address[] calldata tenantOperators,
        uint32[] calldata tierIds,
        string[] calldata tenantIds,
        string[][] calldata initialOrigins
    ) external onlyIssuer returns (address[] memory registries) {
        uint256 count = tenantOperators.length;
        if (count == 0 || count > MAX_TENANT_APPROVAL_BATCH) revert BatchTooLarge();
        if (tierIds.length != count || tenantIds.length != count || initialOrigins.length != count) {
            revert BatchLengthMismatch();
        }
        _validateTenantFactory(factory);
        for (uint256 i = 0; i < count; i++) {
            _validateTenantApproval(tenantOperators[i], tierIds[i], tenantIds[i]);
            for (uint256 j = 0; j < i; j++) {
                if (tenantOperators[i] == tenantOperators[j]) revert DuplicateTenantOperator();
                if (keccak256(bytes(tenantIds[i])) == keccak256(bytes(tenantIds[j]))) {
                    revert DuplicateTenantId();
                }
            }
        }
        registries = new address[](count);
        for (uint256 i = 0; i < count; i++) {
            registries[i] = _approveTenantAndDeploy(
                factory,
                tenantOperators[i],
                tierIds[i],
                tenantIds[i],
                initialOrigins[i]
            );
        }
    }

    /// @notice Revoke (issuer) or renounce (holder) a credential.
    function burn(uint256 tokenId) external {
        address holder = _ownerOf[tokenId];
        if (holder == address(0)) revert UnknownToken();
        if (msg.sender != issuer && msg.sender != holder) revert NotAuthorizedToBurn();
        uint8 role = roleOf[tokenId];
        delete _ownerOf[tokenId];
        delete roleOf[tokenId];
        delete tokenOf[holder];
        delete _approvedTransferTo[tokenId];
        delete tierOf[holder];
        _balanceOf[holder] = 0;
        emit Transfer(holder, address(0), tokenId);
        emit AccessRevoked(holder, tokenId, role);
    }

    /// @notice Convenience revocation by wallet address.
    function revokeAccess(address holder) external onlyIssuer {
        uint256 tokenId = tokenOf[holder];
        if (tokenId == 0) revert UnknownToken();
        uint8 role = roleOf[tokenId];
        delete _ownerOf[tokenId];
        delete roleOf[tokenId];
        delete tokenOf[holder];
        delete _approvedTransferTo[tokenId];
        delete tierOf[holder];
        _balanceOf[holder] = 0;
        emit Transfer(holder, address(0), tokenId);
        emit AccessRevoked(holder, tokenId, role);
    }

    /// @notice Hand issuance to a new operator wallet (e.g. a multisig).
    function setIssuer(address newIssuer) external onlyIssuer {
        if (newIssuer == address(0)) revert ZeroAddress();
        if (newIssuer != issuer) {
            authorityEpoch++;
            emit AuthorityPermissionsInvalidated(authorityEpoch);
        }
        emit IssuerChanged(issuer, newIssuer);
        issuer = newIssuer;
    }

    /// @notice Router-shaped convenience: does this wallet hold a credential
    ///         with at least the given role?
    function hasRole(address holder, uint8 minimumRole) external view returns (bool) {
        uint256 tokenId = tokenOf[holder];
        return tokenId != 0 && roleOf[tokenId] >= minimumRole;
    }
}

